import 'dart:math' as math;
import 'package:flutter/material.dart';

class GameWorldPlanetPage extends StatefulWidget {
  const GameWorldPlanetPage({super.key});
  @override State<GameWorldPlanetPage> createState() => _GameWorldPlanetPageState();
}

class _GameWorldPlanetPageState extends State<GameWorldPlanetPage> with SingleTickerProviderStateMixin {
  late final AnimationController _clock = AnimationController(vsync: this, duration: const Duration(seconds: 120))..repeat();
  int selected = 0;
  final regions = const [
    ('NORTHLAND', 'NINTENDO', 'Northern archive territory'),
    ('WESTERN REACH', 'SEGA', 'Western archive territory'),
    ('SOUTHERN CONTINENT', 'PLAYSTATION', 'Southern archive territory'),
    ('EASTERN HIGHLANDS', 'XBOX', 'Eastern archive territory'),
  ];
  @override void dispose(){_clock.dispose();super.dispose();}
  @override Widget build(BuildContext context){
    final compact=MediaQuery.sizeOf(context).width<820;
    return Scaffold(backgroundColor:const Color(0xFF010307),body:AnimatedBuilder(animation:_clock,builder:(_,__)=>Stack(fit:StackFit.expand,children:[
      CustomPaint(painter:_SpacePainter(_clock.value)),
      Center(child:LayoutBuilder(builder:(_,b){final d=math.min(b.maxWidth*(compact ? .88 : .55),b.maxHeight*(compact ? .52 : .72));return SizedBox.square(dimension:d,child:CustomPaint(painter:_PlanetWorldPainter(_clock.value)));})),
      for(var i=0;i<regions.length;i++) _RegionNode(index:i,selected:selected==i,compact:compact,onTap:()=>setState(()=>selected=i),onOpen:()=>setState(()=>selected=i)),
      SafeArea(child:Padding(padding:EdgeInsets.all(compact?14:32),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
        const Text('GAME-WORLD',style:TextStyle(fontSize:19,letterSpacing:6,fontWeight:FontWeight.w500)),const SizedBox(height:5),
        const Text('PLANETARY ARCHIVE  /  REGIONAL ATLAS',style:TextStyle(fontSize:6.5,letterSpacing:2.6,color:Color(0x62C2D0D5))),
        const Spacer(),Align(alignment:Alignment.topRight,child:Column(crossAxisAlignment:CrossAxisAlignment.end,children:[const Text('WORLD 01',style:TextStyle(fontSize:6,letterSpacing:2,color:Color(0x80C8D6DA))),const SizedBox(height:5),const Text('REGIONS 04  /  STATUS STABLE',style:TextStyle(fontSize:5.5,letterSpacing:1.7,color:Color(0x4FC8D6DA)))])),
        const Spacer(),Center(child:Text('1× CLICK  FOCUS     2× CLICK  ENTER REGION',style:TextStyle(fontSize:6.5,letterSpacing:2,color:Color(0x55FFFFFF)))),
      ]))),
      Positioned(left:compact?14:32,right:compact?14:32,bottom:compact?44:58,child:_RegionPanel(data:regions[selected],index:selected,compact:compact)),
    ])));
  }
}
class _RegionNode extends StatelessWidget {final int index;final bool selected,compact;final VoidCallback onTap,onOpen;const _RegionNode({required this.index,required this.selected,required this.compact,required this.onTap,required this.onOpen});@override Widget build(BuildContext c){final size=MediaQuery.sizeOf(c);final angles=[-2.35,-.75,.75,2.35];final a=angles[index];final rx=size.width*(compact ? .22 : .29),ry=size.height*(compact ? .20 : .29);final center=Offset(size.width*.5+math.cos(a)*rx,size.height*.52+math.sin(a)*ry);final d=(selected?(compact?72:104):(compact?52:76)).toDouble();return Positioned(left:center.dx-d/2,top:center.dy-d/2,width:d,height:d,child:GestureDetector(onTap:onTap,onDoubleTap:onOpen,child:CustomPaint(painter:_MarkerPainter(selected))));}}
class _MarkerPainter extends CustomPainter {final bool selected;const _MarkerPainter(this.selected);@override void paint(Canvas x,Size s){final c=s.center(Offset.zero),r=s.width*.18,h=r*(selected?7:4);x.drawCircle(c,h,Paint()..shader=RadialGradient(colors:[const Color(0x6BA7C8D0).withValues(alpha:selected ? .22 : .055),Colors.transparent]).createShader(Rect.fromCircle(center:c,radius:h)));x.drawCircle(c,r*2.5,Paint()..style=PaintingStyle.stroke..strokeWidth=selected?1.4:.55..color=const Color(0x779CB8C1));x.drawCircle(c,r,Paint()..shader=const RadialGradient(center:Alignment(-.35,-.55),colors:[Color(0xFFF4F8F9),Color(0xFF8BA5AD),Color(0xFF26343B),Color(0xFF030609)]).createShader(Rect.fromCircle(center:c,radius:r)));} @override bool shouldRepaint(covariant _MarkerPainter o)=>o.selected!=selected;}
class _RegionPanel extends StatelessWidget {final (String,String,String) data;final int index;final bool compact;const _RegionPanel({required this.data,required this.index,required this.compact});@override Widget build(BuildContext c)=>Container(padding:EdgeInsets.all(compact?13:18),decoration:BoxDecoration(color:const Color(0xEF060A0E),border:Border.all(color:const Color(0x458CA7B0)),boxShadow:const[BoxShadow(color:Colors.black87,blurRadius:42)]),child:Row(children:[Container(width:3,height:compact?50:62,color:const Color(0xA1A8C3CB)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('REGION ${(index+1).toString().padLeft(2,'0')}  /  ${data.$3}',style:const TextStyle(fontSize:5.5,letterSpacing:1.8,color:Color(0x70B5C6CB))),const SizedBox(height:5),Text(data.$2,style:TextStyle(fontSize:compact?13:18,letterSpacing:2.7)),const SizedBox(height:4),Text(data.$1,style:const TextStyle(fontSize:7.5,color:Color(0x88C7D3D7)))])),if(!compact)const Text(' ENTER REGION ',style:TextStyle(fontSize:6,letterSpacing:1.7,color:Color(0xB7D1D8)))]));}
class _SpacePainter extends CustomPainter {final double phase;const _SpacePainter(this.phase);@override void paint(Canvas x,Size s){final r=Offset.zero&s;x.drawRect(r,Paint()..shader=const RadialGradient(colors:[Color(0xFF0A151D),Color(0xFF02060A),Color(0xFF010204)]).createShader(r));final rnd=math.Random(42);for(var i=0;i<520;i++){final p=Offset(rnd.nextDouble()*s.width,rnd.nextDouble()*s.height);x.drawCircle(p,.15+rnd.nextDouble()*.65,Paint()..color=Colors.white.withValues(alpha:.015+.06*(.5+.5*math.sin(phase*math.pi*2+i))));}final c=Offset(s.width*.5,s.height*.52);for(var i=0;i<5;i++){x.drawOval(Rect.fromCenter(center:c,width:s.width*(.52+i*.1),height:s.height*(.18+i*.045)),Paint()..style=PaintingStyle.stroke..strokeWidth=.45..color=const Color(0x1F91AAB2));}}@override bool shouldRepaint(covariant _SpacePainter o)=>o.phase!=phase;}
class _PlanetWorldPainter extends CustomPainter {final double phase;const _PlanetWorldPainter(this.phase);@override void paint(Canvas x,Size s){final c=Offset(s.width*.5,s.height*.52),r=math.min(s.width,s.height)*.42,rect=Rect.fromCircle(center:c,radius:r);x.drawCircle(c,r*1.12,Paint()..shader=RadialGradient(colors:[const Color(0x5A7FAAB7),const Color(0x1B7FAAB7),Colors.transparent],stops:const[.68,.82,1]).createShader(Rect.fromCircle(center:c,radius:r*1.12)));x.drawCircle(c,r,Paint()..shader=const RadialGradient(center:Alignment(-.4,-.5),colors:[Color(0xFF688A80),Color(0xFF355C53),Color(0xFF18312E),Color(0xFF04090C)],stops:[0,.36,.73,1]).createShader(rect));final land=Paint()..color=const Color(0xA85C7657);final shapes=[[.22,.35,.42,.29,.5,.4,.37,.47,.24,.42],[.52,.28,.66,.24,.76,.36,.67,.48,.53,.41],[.28,.54,.44,.49,.51,.62,.43,.76,.3,.69],[.59,.55,.77,.5,.8,.67,.67,.77,.56,.7]];for(final q in shapes){final p=Path()..moveTo(q[0]*s.width,q[1]*s.height);for(var i=2;i<q.length;i+=2)p.lineTo(q[i]*s.width,q[i+1]*s.height);p.close();x.drawPath(p,land);}final detail=Paint()..style=PaintingStyle.stroke..strokeWidth=.7..color=const Color(0x597B9A86);for(var i=0;i<11;i++){final p=Path()..moveTo(s.width*(.25+i*.05),s.height*.3)..quadraticBezierTo(s.width*(.3+i*.04),s.height*.5,s.width*(.27+i*.045),s.height*.77);x.drawPath(p,detail);}final river=Paint()..style=PaintingStyle.stroke..strokeWidth=1.1..color=const Color(0x7783B5B7);for(var i=0;i<7;i++){final p=Path()..moveTo(s.width*(.3+i*.06),s.height*.36)..cubicTo(s.width*(.24+i*.07),s.height*.48,s.width*(.42+i*.04),s.height*.58,s.width*(.34+i*.05),s.height*.75);x.drawPath(p,river);}final grid=Paint()..style=PaintingStyle.stroke..strokeWidth=.45..color=const Color(0x2D9CB5B6);for(var i=-2;i<=2;i++)x.drawOval(Rect.fromCenter(center:c,width:r*1.9,height:r*(.55+i.abs()*.28)),grid);x.drawCircle(c,r,Paint()..shader=LinearGradient(begin:Alignment.topLeft,end:Alignment.bottomRight,colors:[Colors.transparent,const Color(0xB7000306)],stops:const[.43,1]).createShader(rect));x.drawArc(Rect.fromCircle(center:c,radius:r*1.03),phase*math.pi*2,.8,false,Paint()..style=PaintingStyle.stroke..strokeWidth=1.2..color=const Color(0x659BC8D1));x.drawCircle(c,r,Paint()..style=PaintingStyle.stroke..strokeWidth=r*.035..color=const Color(0x238BB6C1));}@override bool shouldRepaint(covariant _PlanetWorldPainter o)=>o.phase!=phase;}
